const ruc = String($json.RUC ?? '').trim();
const valido = /^\d{11}$/.test(ruc);
return [{json: {
 ruc,
 formatoValido: valido,
 titulo: valido ? 'RUC recibido — verificación oficial pendiente' : 'Revisa el número de RUC',
 mensaje: valido
 ? 'El número tiene 11 dígitos. Este flujo inicial todavía no consulta SUNAT. No se ha comprobado existencia, razón social, estado ni condición. El siguiente paso es conectar el padrón oficial o una API de consulta.'
 : 'Ingresa un RUC de 11 dígitos, sin letras, espacios internos ni guiones. Esta revisión de formato no acredita que la empresa exista.',
 fuente: null,
 fechaPadron: null,
 verificacionOficial: 'PENDIENTE'
}}];
